   670→// MARK: - Color Extension
   671→
   672→extension Color {
   673→    init?(hex: String) {
   674→        let hex = hex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
   675→        var int: UInt64 = 0
   676→        Scanner(string: hex).scanHexInt64(&int)
   677→        let a, r, g, b: UInt64
   678→        switch hex.count {
   679→        case 3: // RGB (12-bit)
   680→            (a, r, g, b) = (255, (int >> 8) * 17, (int >> 4 & 0xF) * 17, (int & 0xF) * 17)
   681→        case 6: // RGB (24-bit)
   682→            (a, r, g, b) = (255, int >> 16, int >> 8 & 0xFF, int & 0xFF)
   683→        case 8: // ARGB (32-bit)
   684→            (a, r, g, b) = (int >> 24, int >> 16 & 0xFF, int >> 8 & 0xFF, int & 0xFF)
   685→        default:
   686→            return nil
   687→        }
   688→        self.init(
   689→            .sRGB,
   690→            red: Double(r) / 255,
   691→            green: Double(g) / 255,
   692→            blue: Double(b) / 255,
   693→            opacity: Double(a) / 255
   694→        )
   695→    }
   696→
   697→    func toHex() -> String {
   698→        guard let components = NSColor(self).cgColor.components, components.count >= 3 else {
   699→            return "#000000"
   700→        }
   701→        let r = Float(components[0])
   702→        let g = Float(components[1])
   703→        let b = Float(components[2])
   704→        return String(format: "#%02lX%02lX%02lX", lroundf(r * 255), lroundf(g * 255), lroundf(b * 255))
   705→    }
   706→}
