   715→    case large
   716→    case extraLarge
   717→
   718→    var id: String { label }
   719→
   720→    var label: String {
   721→        switch self {
   722→        case .small: return "Small"
   723→        case .medium: return "Medium"
   724→        case .large: return "Large"
   725→        case .extraLarge: return "X-Large"
   726→        }
   727→    }
   728→
   729→    var size: Double {
   730→        switch self {
   731→        case .small: return 12
   732→        case .medium: return 16
   733→        case .large: return 20
   734→        case .extraLarge: return 24
   735→        }
   736→    }
   737→}
