   741→enum ThemePreset: CaseIterable, Identifiable {
   742→    case light
   743→    case sepia
   744→    case dark
   745→    case highContrast
   746→
   747→    var id: String { label }
   748→
   749→    var label: String {
   750→        switch self {
   751→        case .light: return "Light"
   752→        case .sepia: return "Sepia"
   753→        case .dark: return "Dark"
   754→        case .highContrast: return "High Contrast"
   755→        }
   756→    }
   757→
   758→    var backgroundColor: String {
   759→        switch self {
   760→        case .light: return "#FFFFFF"
   761→        case .sepia: return "#F4ECD8"
   762→        case .dark: return "#1C1C1E"
   763→        case .highContrast: return "#000000"
   764→        }
   765→    }
   766→
   767→    var textColor: String {
   768→        switch self {
   769→        case .light: return "#000000"
   770→        case .sepia: return "#5B4636"
   771→        case .dark: return "#EBEBF5"
   772→        case .highContrast: return "#FFFFFF"
   773→        }
   774→    }
   775→
   776→    func apply(to settings: AppSettings) {
   777→        settings.backgroundColor = backgroundColor
   778→        settings.textColor = textColor
   779→    }
   780→
   781→    func matches(_ settings: AppSettings) -> Bool {
   782→        settings.backgroundColor == backgroundColor && settings.textColor == textColor
   783→    }
   784→}
