   288→                ZStack(alignment: .leading) {
   289→                    // Background
   290→                    Rectangle()
   291→                        .fill(Color.secondary.opacity(0.15))
   292→
   293→                    // Completed chapters
   294→                    Rectangle()
   295→                        .fill(Color.accentColor.opacity(0.6))
   296→                        .frame(width: chapterWidth * CGFloat(currentChapterIndex))
   297→
   298→                    // Current chapter progress
   299→                    Rectangle()
   300→                        .fill(Color.accentColor)
   301→                        .frame(width: chapterWidth * CGFloat(currentChapterIndex) + chapterWidth * currentScrollPosition)
   302→
   303→                    // Chapter tick marks
   304→                    HStack(spacing: 0) {
   305→                        ForEach(0..<book.chapters.count, id: \.self) { i in
   306→                            Rectangle()
   307→                                .fill(Color.clear)
   308→                                .frame(width: chapterWidth)
   309→                                .overlay(alignment: .trailing) {
   310→                                    if i < book.chapters.count - 1 {
   311→                                        Rectangle()
   312→                                            .fill(Color.primary.opacity(0.2))
   313→                                            .frame(width: 1)
   314→                                    }
   315→                                }
   316→                        }
   317→                    }
   318→                }
   319→            }
   320→            .frame(height: 4)
   321→        }
   322→        .navigationTitle(book.title)
   323→        .toolbar {
   324→            ToolbarItem {
   325→                Menu {
   326→                    ForEach(Array(book.chapters.enumerated()), id: \.offset) { index, chapter in
   327→                        Button {
   328→                            navigateToChapter(index)
   329→                        } label: {
   330→                            HStack {
   331→                                Text(String(repeating: "    ", count: chapter.depth) + chapter.title)
   332→                                    .font(chapter.depth == 0 ? .body.weight(.medium) : .body)
   333→                            }
   334→                        }
   335→                    }
   336→                } label: {
   337→                    Label("Chapters", systemImage: "list.bullet")
   338→                }
   339→            }
   340→        }
   341→        .task {
   342→            await loadState()
   343→        }
   344→        .onChange(of: currentChapterIndex) { _, _ in
   345→            // Scroll to position after chapter change
   346→            // Use delay to let content load/update first
   347→            DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
   348→                scrollToFragmentOrTop()
   349→            }
   350→
   351→            // Re-run search in new chapter if search is active
   352→            if searchState.isSearchActive && searchState.scope == .chapter && !searchState.query.isEmpty {
   353→                // Small delay to let the new chapter content load
   354→                DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
   355→                    performInChapterSearch(searchState.query)
   356→                }
   357→            }
   358→        }
   359→        #if os(macOS)
   360→        .onKeyPress(.leftArrow) {
   361→            if currentChapterIndex > 0 {
   362→                navigateToChapter(currentChapterIndex - 1)
   363→                return .handled
   364→            }
   365→            return .ignored
   366→        }
   367→        .onKeyPress(.rightArrow) {
   368→            if currentChapterIndex < book.chapters.count - 1 {
   369→                navigateToChapter(currentChapterIndex + 1)
   370→                return .handled
   371→            }
   372→            return .ignored
   373→        }
   374→        .onKeyPress(characters: .init(charactersIn: "fF")) { press in
   375→            if press.modifiers.contains(.command) {
   376→                searchState.isSearchActive = true
   377→                return .handled
   378→            }
   379→            return .ignored
   380→        }
   381→        .onKeyPress(.escape) {
   382→            if pendingSelection != nil {
   383→                clearPendingSelection()
   384→                evaluateJavaScript("window.getSelection().removeAllRanges();")
   385→                return .handled
   386→            }
   387→            return .ignored
   388→        }
   389→        #endif
   390→    }
   391→
   392→    private func handleTextSelection(_ selectionData: SelectionData) {
   393→        guard currentChapter != nil else { return }
   394→
   395→        // Check if this highlight already exists (committed)
   396→        if annotations.highlights.contains(where: { $0.selectedText == selectionData.text && $0.cfiRange == selectionData.cfiRange }) {
   397→            return
   398→        }
   399→
   400→        // Store as pending (don't save yet - wait for user to click Highlight or Annotate)
   401→        pendingSelection = selectionData
   402→        pendingHighlightId = UUID()
   403→    }
   404→
   405→    private func clearPendingSelection() {
   406→        pendingSelection = nil
   407→        pendingHighlightId = nil
   408→    }
   409→
   410→    private func commitPendingHighlight() -> Highlight? {
   411→        guard let pending = pendingSelection,
   412→              let pendingId = pendingHighlightId,
   413→              let chapter = currentChapter else { return nil }
   414→
   415→        let highlight = Highlight(
   416→            id: pendingId,
   417→            chapterId: chapter.id,
   418→            selectedText: pending.text,
   419→            surroundingContext: pending.context,
   420→            cfiRange: pending.cfiRange
   421→        )
   422→        annotations.addHighlight(highlight)
   423→        clearPendingSelection()
   424→        return highlight
   425→    }
   426→
   427→    private func handleMarginNoteAction(_ action: MarginNoteAction) {
   428→        Task {
   429→            switch action {
   430→            case .commitHighlight(let highlightId):
   431→                // Commit pending selection if it matches
   432→                if pendingHighlightId == highlightId {
   433→                    if let _ = commitPendingHighlight() {
   434→                        try? await BookStorage.shared.saveAnnotations(annotations)
   435→                    }
   436→                }
   437→
   438→            case .startThread(let highlightId):
   439→                // Provider configuration check will happen in ThreadPanel
   440→                guard threadState.isConfigured else {
   441→                    return
   442→                }
   443→
   444→                // If this is a pending selection, commit it first
   445→                var highlight: Highlight?
   446→                if pendingHighlightId == highlightId {
   447→                    highlight = commitPendingHighlight()
   448→                    if highlight != nil {
   449→                        try? await BookStorage.shared.saveAnnotations(annotations)
   450→                    }
   451→                } else {
   452→                    highlight = annotations.highlights.first(where: { $0.id == highlightId })
   453→                }
   454→
   455→                guard let highlight = highlight else { return }
   456→
   457→                // Set loading state - triggers margin note update
   458→                loadingHighlightId = highlightId
   459→
   460→                if let thread = await threadState.startThread(
   461→                    for: highlight,
   462→                    book: book,
   463→                    chapter: currentChapter,
   464→                    bookId: annotations.bookId
   465→                ) {
   466→                    annotations.addThread(to: highlightId, thread: thread)
   467→                    try? await BookStorage.shared.saveAnnotations(annotations)
   468→                }
   469→
   470→                // Clear loading state - triggers margin note update with content
   471→                loadingHighlightId = nil
   472→
   473→            case .sendFollowUp(let highlightId, let message):
   474→                // Provider configuration check will happen in ThreadPanel
   475→                guard threadState.isConfigured else {
   476→                    return
   477→                }
   478→
   479→                guard let highlight = annotations.highlights.first(where: { $0.id == highlightId }) else { return }
   480→
   481→                // Set loading state
   482→                loadingHighlightId = highlightId
   483→
   484→                // Get the existing thread from the highlight
   485→                let existingThread = highlight.threads.first
   486→
   487→                if let thread = await threadState.continueThread(
   488→                    message: message,
   489→                    highlight: highlight,
   490→                    book: book,
   491→                    existingThread: existingThread
   492→                ) {
   493→                    // Update the thread in annotations
   494→                    if let highlightIndex = annotations.highlights.firstIndex(where: { $0.id == highlightId }),
   495→                       let threadIndex = annotations.highlights[highlightIndex].threads.firstIndex(where: { $0.id == thread.id }) {
   496→                        annotations.highlights[highlightIndex].threads[threadIndex] = thread
   497→                        try? await BookStorage.shared.saveAnnotations(annotations)
   498→                    }
   499→                }
   500→
   501→                // Clear loading state
   502→                loadingHighlightId = nil
   503→
   504→            case .deleteHighlight(let highlightId):
   505→                // If deleting a pending selection, just clear it
   506→                if pendingHighlightId == highlightId {
   507→                    clearPendingSelection()
   508→                } else {
   509→                    annotations.removeHighlight(id: highlightId)
   510→                    try? await BookStorage.shared.saveAnnotations(annotations)
   511→                }
   512→            }
   513→        }
   514→    }
   515→
   516→    private func navigateToChapter(_ index: Int) {
   517→        guard index >= 0 && index < book.chapters.count else { return }
   518→        clearPendingSelection()  // Discard uncommitted selection on chapter change
   519→
   520→        // Set navigation guard to prevent scroll tracking feedback loop
   521→        isNavigatingProgrammatically = true
   522→        evaluateJavaScript("CruxViewportTracker.beginProgrammaticNavigation();")
   523→
   524→        // Capture fragment and file path for scroll handling
   525→        let newFilePath = book.chapters[index].filePath
   526→        let sameFile = previousFilePath == newFilePath
   527→        pendingFragment = book.chapters[index].fragment
   528→
   529→        // If navigating within same file to a chapter without fragment, scroll to top
   530→        if sameFile && pendingFragment == nil {
   531→            pendingFragment = "__TOP__"  // Sentinel to trigger scroll to top
   532→        }
   533→        previousFilePath = newFilePath
   534→
   535→        // Clear search state on chapter change (search again in new chapter)
   536→        if searchState.isSearchActive && searchState.scope == .chapter {
   537→            searchState.inChapterMatchCount = 0
   538→            searchState.inChapterCurrentIndex = 0
   539→        }
   540→
   541→        currentChapterIndex = index
   542→        saveProgress()
   543→
   544→        // End programmatic navigation after scroll settles
   545→        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
   546→            isNavigatingProgrammatically = false
   547→            evaluateJavaScript("CruxViewportTracker.endProgrammaticNavigation();")
   548→        }
   549→    }
   550→
   551→    private func saveProgress() {
   552→        storedBook?.updateProgress(chapter: currentChapterIndex, total: book.chapters.count, scroll: currentScrollPosition)
   553→    }
   554→
   555→    private func scrollToFragmentOrTop() {
   556→        guard let fragment = pendingFragment else { return }
   557→        pendingFragment = nil
   558→
   559→        if fragment == "__TOP__" {
   560→            // Scroll to top of chapter
   561→            evaluateJavaScript("window.scrollTo(0, 0);")
   562→        } else {
   563→            // Scroll to anchor
   564→            let escaped = fragment.replacingOccurrences(of: "'", with: "\\'")
   565→            evaluateJavaScript("CruxHighlighter.scrollToAnchor('\(escaped)');")
   566→        }
   567→    }
   568→
   569→    private func handleVisibleSectionChange(_ chapterIndex: Int, scrollPosition: Double) {
   570→        // Always track scroll position
   571→        currentScrollPosition = scrollPosition
   572→
   573→        // Guard against feedback loops during programmatic navigation
   574→        guard !isNavigatingProgrammatically else { return }
   575→
   576→        // Update chapter if changed
   577→        if chapterIndex != currentChapterIndex {
   578→            guard chapterIndex >= 0 && chapterIndex < book.chapters.count else { return }
   579→            currentChapterIndex = chapterIndex
   580→            previousFilePath = book.chapters[chapterIndex].filePath
   581→        }
   582→
   583→        saveProgress()
   584→    }
   585→
   586→    private func initializeViewportTracking() {
   587→        guard let chapter = currentChapter else { return }
   588→        // Build anchor list for current file and initialize viewport tracker
   589→        var anchors: [[String: Any]] = []
   590→
   591→        for (index, ch) in book.chapters.enumerated() {
   592→            guard ch.filePath == chapter.filePath else { continue }
   593→
   594→            if let fragment = ch.fragment {
   595→                anchors.append(["id": fragment, "chapterIndex": index, "isFileStart": false])
   596→            } else {
   597→                anchors.append(["id": "__crux_doc_start__", "chapterIndex": index, "isFileStart": true])
   598→            }
   599→        }
   600→
   601→        guard !anchors.isEmpty,
   602→              let jsonData = try? JSONSerialization.data(withJSONObject: anchors),
   603→              let jsonString = String(data: jsonData, encoding: .utf8) else { return }
   604→
   605→        evaluateJavaScript("CruxViewportTracker.init(\(jsonString));")
   606→    }
   607→
   608→    private func loadState() async {
   609→        // Load saved chapter position and scroll
   610→        if let stored = storedBook {
   611→            currentChapterIndex = min(stored.currentChapterIndex, book.chapters.count - 1)
   612→            pendingScrollPosition = stored.scrollPosition
   613→        }
   614→
   615→        // Initialize file path tracking
   616→        if currentChapterIndex < book.chapters.count {
   617→            previousFilePath = book.chapters[currentChapterIndex].filePath
   618→        }
   619→
   620→        // Load annotations
   621→        do {
   622→            annotations = try await BookStorage.shared.loadAnnotations(for: bookId)
   623→        } catch {
   624→            annotations = BookAnnotations(bookId: bookId)
   625→        }
   626→    }
   627→
   628→    private func restoreScrollPositionIfNeeded() {
   629→        guard let scrollPosition = pendingScrollPosition, scrollPosition > 0 else { return }
   630→        pendingScrollPosition = nil
   631→
   632→        // Set navigation guard to prevent the scroll from updating our saved position
   633→        isNavigatingProgrammatically = true
   634→        evaluateJavaScript("CruxViewportTracker.beginProgrammaticNavigation();")
   635→
   636→        // Delay to ensure content is fully rendered before restoring position
   637→        DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
   638→            evaluateJavaScript("CruxHighlighter.setScrollPosition(\(scrollPosition));")
   639→
   640→            // End programmatic navigation after scroll settles
   641→            DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
   642→                isNavigatingProgrammatically = false
   643→                evaluateJavaScript("CruxViewportTracker.endProgrammaticNavigation();")
   644→            }
   645→        }
   646→    }
   647→
   648→    // MARK: - Search
   649→
   650→    private func performInChapterSearch(_ query: String) {
   651→        guard searchState.scope == .chapter else { return }
   652→        let escaped = query.replacingOccurrences(of: "\\", with: "\\\\")
   653→                          .replacingOccurrences(of: "'", with: "\\'")
   654→        let js = "CruxSearch.search('\(escaped)');"
   655→        evaluateJavaScript(js)
   656→    }
   657→
   658→    private func navigateSearchResult(forward: Bool) {
   659→        if searchState.scope == .chapter {
   660→            let js = forward ? "CruxSearch.nextMatch();" : "CruxSearch.previousMatch();"
   661→            evaluateJavaScript(js)
   662→        }
   663→    }
   664→
   665→    private func closeSearch() {
   666→        evaluateJavaScript("CruxSearch.clearHighlights();")
   667→        searchState.isSearchActive = false
   668→        searchState.reset()
   669→    }
   670→
   671→    private func handleScopeChange(_ scope: SearchScope) {
   672→        // Clear in-chapter highlights when switching scopes
   673→        if scope == .book {
   674→            evaluateJavaScript("CruxSearch.clearHighlights();")
   675→            searchState.inChapterMatchCount = 0
   676→            searchState.inChapterCurrentIndex = 0
   677→            performBookSearch(searchState.query)
   678→        } else {
   679→            searchState.bookMatches = []
   680→            // Re-run in-chapter search
   681→            performInChapterSearch(searchState.query)
   682→        }
   683→    }
   684→
   685→    private func performBookSearch(_ query: String) {
   686→        guard !query.isEmpty else {
   687→            searchState.bookMatches = []
   688→            return
   689→        }
   690→
   691→        var matches: [SearchMatch] = []
   692→
   693→        for (index, chapter) in book.chapters.enumerated() {
   694→            let plainText = HTMLTextExtractor.extractText(from: chapter.content)
   695→            let chapterMatches = HTMLTextExtractor.findMatches(in: plainText, query: query)
   696→
   697→            for (matchIndex, match) in chapterMatches.enumerated() {
   698→                matches.append(SearchMatch(
   699→                    text: match.snippet,
   700→                    chapterId: chapter.id,
   701→                    chapterTitle: chapter.title,
   702→                    chapterIndex: index,
   703→                    matchIndex: matchIndex
   704→                ))
   705→            }
   706→        }
   707→
   708→        searchState.bookMatches = matches
   709→    }
   710→
   711→    private func evaluateJavaScript(_ js: String) {
   712→        // Access the webView through the view hierarchy
   713→        // This is a workaround since we don't have direct access to the coordinator
   714→        #if os(macOS)
   715→        if let window = NSApplication.shared.keyWindow,
   716→           let webView = findWebView(in: window.contentView) {
   717→            webView.evaluateJavaScript(js, completionHandler: nil)
   718→        }
   719→        #else
   720→        if let windowScene = UIApplication.shared.connectedScenes.first as? UIWindowScene,
   721→           let window = windowScene.windows.first,
   722→           let webView = findWebView(in: window) {
   723→            webView.evaluateJavaScript(js, completionHandler: nil)
   724→        }
   725→        #endif
   726→    }
   727→
   728→    #if os(macOS)
   729→    private func findWebView(in view: NSView?) -> WKWebView? {
   730→        guard let view = view else { return nil }
   731→        if let webView = view as? WKWebView {
   732→            return webView
   733→        }
   734→        for subview in view.subviews {
   735→            if let found = findWebView(in: subview) {
   736→                return found
   737→            }
   738→        }
   739→        return nil
   740→    }
   741→    #else
   742→    private func findWebView(in view: UIView?) -> WKWebView? {
   743→        guard let view = view else { return nil }
   744→        if let webView = view as? WKWebView {
   745→            return webView
   746→        }
   747→        for subview in view.subviews {
   748→            if let found = findWebView(in: subview) {
   749→                return found
   750→            }
   751→        }
   752→        return nil
   753→    }
   754→    #endif
   755→}
