   757→// WebView for rendering EPUB HTML content
   758→struct EPUBWebView: View {
   759→    let chapter: Chapter
   760→    let highlights: [Highlight]
   761→    let marginNotes: [MarginNoteData]
   762→    let onTextSelected: (SelectionData) -> Void
   763→    let onHighlightTapped: (UUID) -> Void
   764→    var onMarginNoteAction: ((MarginNoteAction) -> Void)? = nil
   765→    var onSearchResults: ((Int, Int) -> Void)? = nil
   766→    var onContentLoaded: (() -> Void)? = nil
   767→    var onVisibleSection: ((Int, Double) -> Void)? = nil
   768→
   769→    @Query private var settings: [AppSettings]
