   776→            fontSize: appSettings.fontSize,
   777→            lineHeight: appSettings.lineHeight,
   778→            paragraphSpacing: appSettings.paragraphSpacing,
   779→            marginWidth: appSettings.marginWidth,
   780→            backgroundColor: appSettings.backgroundColor,
   781→            textColor: appSettings.textColor
   782→        )
   783→    }
   784→
   785→    var body: some View {
   786→        EPUBWebViewRepresentable(
   787→            html: chapter.content,
   788→            highlights: highlights,
   789→            marginNotes: marginNotes,
   790→            customCSS: customCSS,
   791→            onTextSelected: onTextSelected,
   792→            onHighlightTapped: onHighlightTapped,
   793→            onMarginNoteAction: onMarginNoteAction,
   794→            onSearchResults: onSearchResults,
   795→            onContentLoaded: onContentLoaded,
