   228→struct ProviderEditView: View {
   229→    @Environment(\.dismiss) private var dismiss
   230→    let provider: AIProviderConfig?
   231→    let providerManager: AIProviderManager
   232→
   233→    @State private var name: String
   234→    @State private var providerType: ProviderType
   235→    @State private var apiKey: String
   236→    @State private var baseURL: String
   237→    @State private var model: String
   238→    @State private var isActive: Bool
   239→    @State private var isTesting = false
   240→    @State private var testResult: Result<Bool, Error>?
   241→
   242→    init(provider: AIProviderConfig?, providerManager: AIProviderManager) {
   243→        self.provider = provider
   244→        self.providerManager = providerManager
   245→
   246→        _name = State(initialValue: provider?.name ?? "")
   247→        _providerType = State(initialValue: provider?.providerType ?? .claude)
   248→        _apiKey = State(initialValue: provider?.apiKey ?? "")
   249→        _baseURL = State(initialValue: provider?.baseURL ?? "")
   250→        _model = State(initialValue: provider?.model ?? "")
   251→        _isActive = State(initialValue: provider?.isActive ?? false)
   252→    }
   253→
   254→    var body: some View {
   255→        NavigationStack {
   256→            Form {
   257→                Section("Basic Information") {
   258→                    TextField("Name", text: $name, prompt: Text("My AI Provider"))
   259→
   260→                    Picker("Type", selection: $providerType) {
   261→                        ForEach(ProviderType.allCases) { type in
   262→                            Text(type.displayName).tag(type)
   263→                        }
   264→                    }
   265→                    .onChange(of: providerType) { _, newType in
   266→                        // Auto-fill defaults
   267→                        if baseURL.isEmpty {
   268→                            baseURL = newType.defaultBaseURL ?? ""
   269→                        }
   270→                        if model.isEmpty && !newType.defaultModels.isEmpty {
   271→                            model = newType.defaultModels.first ?? ""
   272→                        }
   273→                    }
   274→                }
   275→
   276→                Section("Authentication") {
   277→                    SecureField("API Key", text: $apiKey, prompt: Text("sk-..."))
   278→                }
   279→
   280→                Section("Configuration") {
   281→                    if providerType.requiresBaseURL || !baseURL.isEmpty {
   282→                        TextField("Base URL", text: $baseURL, prompt: Text(providerType.defaultBaseURL ?? "https://..."))
   283→                    }
   284→
   285→                    if !providerType.defaultModels.isEmpty {
   286→                        Picker("Model", selection: $model) {
   287→                            ForEach(providerType.defaultModels, id: \.self) { modelName in
   288→                                Text(modelName).tag(modelName)
   289→                            }
   290→                        }
   291→                    } else {
   292→                        TextField("Model (optional)", text: $model, prompt: Text("gpt-4o"))
   293→                    }
   294→                }
   295→
   296→                Section("Activation") {
   297→                    Toggle("Set as active provider", isOn: $isActive)
   298→                }
   299→
   300→                Section {
   301→                    Button("Test Connection") {
   302→                        Task {
   303→                            await testConnection()
   304→                        }
   305→                    }
   306→                    .disabled(isTesting || !isValid)
   307→
   308→                    if let result = testResult {
   309→                        switch result {
   310→                        case .success:
   311→                            Label("Connection successful", systemImage: "checkmark.circle.fill")
   312→                                .foregroundStyle(.green)
   313→                        case .failure(let error):
   314→                            Label(error.localizedDescription, systemImage: "xmark.circle.fill")
   315→                                .foregroundStyle(.red)
   316→                                .font(.caption)
   317→                        }
   318→                    }
   319→
   320→                    if isTesting {
   321→                        HStack {
   322→                            ProgressView()
   323→                            Text("Testing...")
   324→                        }
   325→                    }
   326→                }
   327→            }
   328→            .formStyle(.grouped)
   329→            .navigationTitle(provider == nil ? "Add Provider" : "Edit Provider")
   330→            .toolbar {
   331→                ToolbarItem(placement: .cancellationAction) {
   332→                    Button("Cancel") {
   333→                        dismiss()
   334→                    }
   335→                }
   336→
   337→                ToolbarItem(placement: .confirmationAction) {
   338→                    Button("Save") {
   339→                        saveProvider()
   340→                    }
   341→                    .disabled(!isValid)
   342→                }
   343→            }
   344→        }
   345→        .frame(width: 500, height: 600)
   346→    }
   347→
   348→    private var isValid: Bool {
   349→        !name.isEmpty && !apiKey.isEmpty &&
   350→        (providerType != .custom || !baseURL.isEmpty)
   351→    }
   352→
   353→    private func testConnection() async {
   354→        isTesting = true
   355→        testResult = nil
   356→
   357→        let testConfig: AIProviderConfig
   358→        if let existing = provider {
   359→            testConfig = existing
   360→            testConfig.name = name
   361→            testConfig.providerType = providerType
   362→            testConfig.apiKey = apiKey
   363→            testConfig.baseURL = baseURL.isEmpty ? nil : baseURL
   364→            testConfig.model = model.isEmpty ? nil : model
   365→        } else {
   366→            testConfig = AIProviderConfig(
   367→                name: name,
   368→                type: providerType,
   369→                apiKey: apiKey,
   370→                baseURL: baseURL.isEmpty ? nil : baseURL,
   371→                model: model.isEmpty ? nil : model
   372→            )
   373→        }
   374→
   375→        do {
   376→            let success = try await providerManager.testProvider(testConfig)
   377→            testResult = .success(success)
   378→        } catch {
   379→            testResult = .failure(error)
   380→        }
   381→
   382→        isTesting = false
   383→    }
   384→
   385→    private func saveProvider() {
   386→        do {
   387→            if let existing = provider {
   388→                existing.name = name
   389→                existing.providerType = providerType
   390→                existing.apiKey = apiKey
   391→                existing.baseURL = baseURL.isEmpty ? nil : baseURL
   392→                existing.model = model.isEmpty ? nil : model
   393→                existing.isActive = isActive
   394→
   395→                try providerManager.updateProvider(existing)
   396→
   397→                if isActive {
   398→                    try providerManager.setActiveProvider(existing)
   399→                }
   400→            } else {
   401→                let newProvider = AIProviderConfig(
   402→                    name: name,
   403→                    type: providerType,
   404→                    apiKey: apiKey,
   405→                    baseURL: baseURL.isEmpty ? nil : baseURL,
   406→                    model: model.isEmpty ? nil : model,
   407→                    isActive: isActive
   408→                )
   409→
   410→                try providerManager.createProvider(newProvider)
   411→
   412→                if isActive {
   413→                    try providerManager.setActiveProvider(newProvider)
   414→                }
   415→            }
   416→
   417→            dismiss()
   418→        } catch {
   419→            testResult = .failure(error)
   420→        }
   421→    }
   422→}
