                        Spacer()
                        Text("\(Int(appSettings.marginWidth))px")
                            .fontWeight(.medium)
                            .monospacedDigit()
                    }
                    Slider(
                        value: Binding(
                            get: { appSettings.marginWidth },
                            set: { appSettings.marginWidth = $0; save() }
                        ),
                        in: 20...200,
