        VStack(alignment: .leading, spacing: 8) {
            // Book title and date header
            HStack(spacing: 8) {
                Image(systemName: "book.fill")
                    .font(.caption2)
                    .foregroundStyle(.blue)

                Text(item.bookTitle)
                    .font(.caption)
                    .fontWeight(.medium)
                    .foregroundStyle(.secondary)
