                                        .font(.title2)
                                }
                                .disabled(followUpText.isEmpty)
                            }
                        } else {
                            HStack {
                                ProgressView()
                                    .scaleEffect(0.8)
                                Text("Thinking...")
                                    .foregroundStyle(.secondary)
                            }
