import SwiftUI

struct TableOfContentsView: View {
    let chapters: [Chapter]
    let currentChapterIndex: Int
    let onSelectChapter: (Int) -> Void

    @State private var searchQuery = ""

    private var filteredChapters: [(index: Int, chapter: Chapter)] {
        let indexed = chapters.enumerated().map { ($0, $1) }
        guard !searchQuery.isEmpty else { return indexed }

        return indexed.filter { _, chapter in
            chapter.title.localizedCaseInsensitiveContains(searchQuery)
        }
    }

    var body: some View {
        VStack(spacing: 0) {
            // Search bar
            HStack(spacing: 8) {
                Image(systemName: "magnifyingglass")
                    .foregroundStyle(.secondary)
                    .font(.system(size: 12))

                TextField("Search chapters...", text: $searchQuery)
                    .textFieldStyle(.plain)
                    .font(.system(size: 12))

                if !searchQuery.isEmpty {
                    Button {
                        searchQuery = ""
                    } label: {
                        Image(systemName: "xmark.circle.fill")
                            .foregroundStyle(.secondary)
                            .font(.system(size: 12))
                    }
                    .buttonStyle(.plain)
                }
            }
            .padding(.horizontal, 12)
            .padding(.vertical, 8)
            .background(Color(.textBackgroundColor).opacity(0.5))

            Divider()

            // Chapter list
            if filteredChapters.isEmpty {
                ContentUnavailableView.search(text: searchQuery)
            } else {
                ScrollViewReader { proxy in
                    List(filteredChapters, id: \.index) { index, chapter in
                        ChapterRow(
                            chapter: chapter,
                            isCurrentChapter: index == currentChapterIndex,
                            onTap: {
                                onSelectChapter(index)
                            }
                        )
                        .id(index)
                        .listRowInsets(EdgeInsets(
                            top: 4,
                            leading: CGFloat(8 + (chapter.depth * 12)),
                            bottom: 4,
                            trailing: 8
                        ))
                    }
                    .listStyle(.plain)
                    .scrollContentBackground(.hidden)
                    .onAppear {
                        // Scroll to current chapter on appear
                        proxy.scrollTo(currentChapterIndex, anchor: .center)
                    }
                    .onChange(of: currentChapterIndex) { _, newIndex in
                        withAnimation {
                            proxy.scrollTo(newIndex, anchor: .center)
                        }
                    }
                }
            }
        }
    }
}

struct ChapterRow: View {
    let chapter: Chapter
    let isCurrentChapter: Bool
    let onTap: () -> Void

    var body: some View {
        Button(action: onTap) {
            HStack(spacing: 8) {
                // Current chapter indicator
                Circle()
                    .fill(isCurrentChapter ? Color.accentColor : Color.clear)
                    .frame(width: 6, height: 6)

                VStack(alignment: .leading, spacing: 2) {
                    Text(chapter.title)
                        .font(.system(size: 13, weight: isCurrentChapter ? .semibold : .regular))
                        .foregroundStyle(isCurrentChapter ? Color.accentColor : Color.primary)
                        .lineLimit(2)
                        .multilineTextAlignment(.leading)

                    if let snippet = chapter.content.prefix(100).trimmingCharacters(in: .whitespacesAndNewlines).components(separatedBy: .newlines).first,
                       !snippet.isEmpty {
                        Text(snippet)
                            .font(.system(size: 11))
                            .foregroundStyle(.secondary)
                            .lineLimit(1)
                    }
                }

                Spacer()

                if isCurrentChapter {
                    Image(systemName: "book.fill")
                        .font(.system(size: 10))
                        .foregroundColor(.accentColor)
                }
            }
            .padding(.vertical, 4)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .background(
            isCurrentChapter
                ? Color.accentColor.opacity(0.08)
                : Color.clear
        )
        .clipShape(RoundedRectangle(cornerRadius: 6))
    }
}

#Preview {
