   865→extension Color {
   866→    init?(hex: String) {
   867→        let hex = hex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
   868→        var int: UInt64 = 0
   869→        Scanner(string: hex).scanHexInt64(&int)
   870→        let a, r, g, b: UInt64
   871→        switch hex.count {
   872→        case 3: // RGB (12-bit)
   873→            (a, r, g, b) = (255, (int >> 8) * 17, (int >> 4 & 0xF) * 17, (int & 0xF) * 17)
   874→        case 6: // RGB (24-bit)
   875→            (a, r, g, b) = (255, int >> 16, int >> 8 & 0xFF, int & 0xFF)
   876→        case 8: // ARGB (32-bit)
   877→            (a, r, g, b) = (int >> 24, int >> 16 & 0xFF, int >> 8 & 0xFF, int & 0xFF)
   878→        default:
   879→            return nil
   880→        }
   881→        self.init(
   882→            .sRGB,
   883→            red: Double(r) / 255,
   884→            green: Double(g) / 255,
   885→            blue: Double(b) / 255,
   886→            opacity: Double(a) / 255
   887→        )
   888→    }
