   893→        }
   894→        let r = Float(components[0])
   895→        let g = Float(components[1])
   896→        let b = Float(components[2])
   897→        return String(format: "#%02lX%02lX%02lX", lroundf(r * 255), lroundf(g * 255), lroundf(b * 255))
