   342→struct ProviderEditView: View {
   343→    @Environment(\.dismiss) private var dismiss
   344→    let provider: AIProviderConfig?
   345→    let providerManager: AIProviderManager
   346→
   347→    @State private var name: String
   348→    @State private var providerType: ProviderType
   349→    @State private var apiKey: String
   350→    @State private var baseURL: String
   351→    @State private var model: String
   352→    @State private var isActive: Bool
   353→    @State private var isTesting = false
   354→    @State private var testResult: Result<Bool, Error>?
   355→
   356→    init(provider: AIProviderConfig?, providerManager: AIProviderManager) {
   357→        self.provider = provider
   358→        self.providerManager = providerManager
   359→
   360→        _name = State(initialValue: provider?.name ?? "")
   361→        _providerType = State(initialValue: provider?.providerType ?? .claude)
   362→        _apiKey = State(initialValue: provider?.apiKey ?? "")
   363→        _baseURL = State(initialValue: provider?.baseURL ?? "")
   364→        _model = State(initialValue: provider?.model ?? "")
   365→        _isActive = State(initialValue: provider?.isActive ?? false)
   366→    }
   367→
   368→    var body: some View {
   369→        NavigationStack {
   370→            Form {
   371→                Section("Basic Information") {
   372→                    TextField("Name", text: $name, prompt: Text("My AI Provider"))
   373→
   374→                    Picker("Type", selection: $providerType) {
   375→                        ForEach(ProviderType.allCases) { type in
   376→                            Text(type.displayName).tag(type)
   377→                        }
   378→                    }
   379→                    .onChange(of: providerType) { _, newType in
   380→                        // Auto-fill defaults
   381→                        if baseURL.isEmpty {
   382→                            baseURL = newType.defaultBaseURL ?? ""
   383→                        }
   384→                        if model.isEmpty && !newType.defaultModels.isEmpty {
   385→                            model = newType.defaultModels.first ?? ""
   386→                        }
   387→                    }
   388→                }
   389→
   390→                Section("Authentication") {
   391→                    SecureField("API Key", text: $apiKey, prompt: Text("sk-..."))
   392→                }
   393→
   394→                Section("Configuration") {
   395→                    if providerType.requiresBaseURL || !baseURL.isEmpty {
   396→                        TextField("Base URL", text: $baseURL, prompt: Text(providerType.defaultBaseURL ?? "https://..."))
   397→                    }
   398→
   399→                    if !providerType.defaultModels.isEmpty {
   400→                        Picker("Model", selection: $model) {
   401→                            ForEach(providerType.defaultModels, id: \.self) { modelName in
   402→                                Text(modelName).tag(modelName)
   403→                            }
   404→                        }
   405→                    } else {
   406→                        TextField("Model (optional)", text: $model, prompt: Text("gpt-4o"))
   407→                    }
   408→                }
   409→
   410→                Section("Activation") {
   411→                    Toggle("Set as active provider", isOn: $isActive)
   412→                }
   413→
   414→                Section {
   415→                    Button("Test Connection") {
   416→                        Task {
   417→                            await testConnection()
   418→                        }
   419→                    }
   420→                    .disabled(isTesting || !isValid)
   421→
   422→                    if let result = testResult {
   423→                        switch result {
   424→                        case .success:
   425→                            Label("Connection successful", systemImage: "checkmark.circle.fill")
   426→                                .foregroundStyle(.green)
   427→                        case .failure(let error):
   428→                            Label(error.localizedDescription, systemImage: "xmark.circle.fill")
   429→                                .foregroundStyle(.red)
   430→                                .font(.caption)
   431→                        }
   432→                    }
   433→
   434→                    if isTesting {
   435→                        HStack {
   436→                            ProgressView()
   437→                            Text("Testing...")
   438→                        }
   439→                    }
   440→                }
   441→            }
   442→            .formStyle(.grouped)
   443→            .navigationTitle(provider == nil ? "Add Provider" : "Edit Provider")
   444→            .toolbar {
   445→                ToolbarItem(placement: .cancellationAction) {
   446→                    Button("Cancel") {
   447→                        dismiss()
   448→                    }
   449→                }
   450→
   451→                ToolbarItem(placement: .confirmationAction) {
   452→                    Button("Save") {
   453→                        saveProvider()
   454→                    }
   455→                    .disabled(!isValid)
   456→                }
   457→            }
   458→        }
   459→        .frame(width: 500, height: 600)
   460→    }
   461→
   462→    private var isValid: Bool {
   463→        !name.isEmpty && !apiKey.isEmpty &&
   464→        (providerType != .custom || !baseURL.isEmpty)
   465→    }
   466→
   467→    private func testConnection() async {
   468→        isTesting = true
   469→        testResult = nil
   470→
   471→        let testConfig: AIProviderConfig
   472→        if let existing = provider {
   473→            testConfig = existing
   474→            testConfig.name = name
   475→            testConfig.providerType = providerType
   476→            testConfig.apiKey = apiKey
   477→            testConfig.baseURL = baseURL.isEmpty ? nil : baseURL
   478→            testConfig.model = model.isEmpty ? nil : model
   479→        } else {
   480→            testConfig = AIProviderConfig(
   481→                name: name,
   482→                type: providerType,
   483→                apiKey: apiKey,
   484→                baseURL: baseURL.isEmpty ? nil : baseURL,
   485→                model: model.isEmpty ? nil : model
   486→            )
   487→        }
   488→
   489→        do {
   490→            let success = try await providerManager.testProvider(testConfig)
   491→            testResult = .success(success)
   492→        } catch {
   493→            testResult = .failure(error)
   494→        }
   495→
   496→        isTesting = false
   497→    }
   498→
   499→    private func saveProvider() {
   500→        do {
   501→            if let existing = provider {
   502→                existing.name = name
   503→                existing.providerType = providerType
   504→                existing.apiKey = apiKey
   505→                existing.baseURL = baseURL.isEmpty ? nil : baseURL
   506→                existing.model = model.isEmpty ? nil : model
   507→                existing.isActive = isActive
   508→
   509→                try providerManager.updateProvider(existing)
   510→
   511→                if isActive {
   512→                    try providerManager.setActiveProvider(existing)
   513→                }
   514→            } else {
   515→                let newProvider = AIProviderConfig(
   516→                    name: name,
   517→                    type: providerType,
   518→                    apiKey: apiKey,
   519→                    baseURL: baseURL.isEmpty ? nil : baseURL,
   520→                    model: model.isEmpty ? nil : model,
   521→                    isActive: isActive
   522→                )
   523→
   524→                try providerManager.createProvider(newProvider)
   525→
   526→                if isActive {
   527→                    try providerManager.setActiveProvider(newProvider)
   528→                }
   529→            }
   530→
   531→            dismiss()
   532→        } catch {
   533→            testResult = .failure(error)
   534→        }
   535→    }
   536→}
