                                RoundedRectangle(cornerRadius: 8)
                                    .stroke(Color.blue.opacity(0.2), lineWidth: 1)
                            )
                        }

                        // Start thread button or loading state
                        if state.isLoading && state.currentThread == nil {
                            VStack(spacing: 12) {
                                ProgressView()
                                    .scaleEffect(1.0)

                                VStack(spacing: 4) {
                                    Text("Analyzing passage...")
