                                    HStack(spacing: 8) {
                                        Image(systemName: "exclamationmark.triangle.fill")
                                            .foregroundStyle(.orange)

                                        Text("No AI provider configured")
                                            .font(.caption)
                                            .foregroundStyle(.primary)
                                    }

                                    #if os(macOS)
                                    Button {
                                        NSApp.sendAction(Selector(("showSettingsWindow:")), to: nil, from: nil)
                                    } label: {
                                        HStack(spacing: 4) {
                                            Image(systemName: "gearshape.fill")
                                                .font(.caption)

                                            Text("Open Settings")
                                                .font(.caption)
                                        }
                                        .padding(.horizontal, 12)
                                        .padding(.vertical, 6)
                                        .background(Color.orange.opacity(0.15))
                                        .foregroundStyle(.orange)
                                        .clipShape(RoundedRectangle(cornerRadius: 6))
                                    }
                                    .buttonStyle(.plain)
                                    #else
                                    Text("Configure an AI provider in Settings")
                                        .font(.caption2)
                                        .foregroundStyle(.secondary)
                                    #endif
                                }
                                .padding()
                                .frame(maxWidth: .infinity)
                                .background(Color.orange.opacity(0.08))
                                .clipShape(RoundedRectangle(cornerRadius: 10))
                                .overlay(
                                    RoundedRectangle(cornerRadius: 10)
                                        .stroke(Color.orange.opacity(0.2), lineWidth: 1)
                                )
                            }
                        }
                    }

                    // Thread messages
                    if let thread = state.currentThread {
                        ForEach(thread.messages) { message in
                            ThreadMessageView(message: message)
                        }

                        // Follow-up input
                        if !state.isLoading {
                            HStack(spacing: 8) {
                                HStack {
                                    Image(systemName: "bubble.left")
                                        .font(.caption)
                                        .foregroundStyle(.secondary)

                                    TextField("Ask a follow-up...", text: $followUpText)
                                        .textFieldStyle(.plain)
                                        .onSubmit {
                                            onSendFollowUp()
                                        }
                                }
                                .padding(.horizontal, 12)
                                .padding(.vertical, 10)
                                .background(Color(.textBackgroundColor))
                                .clipShape(RoundedRectangle(cornerRadius: 10))
                                .overlay(
                                    RoundedRectangle(cornerRadius: 10)
                                        .stroke(Color.secondary.opacity(0.2), lineWidth: 1)
                                )

                                Button {
                                    onSendFollowUp()
                                } label: {
                                    ZStack {
                                        Circle()
                                            .fill(
                                                LinearGradient(
                                                    colors: followUpText.isEmpty
                                                        ? [Color.secondary.opacity(0.1), Color.secondary.opacity(0.1)]
                                                        : [Color.blue, Color.purple],
                                                    startPoint: .topLeading,
                                                    endPoint: .bottomTrailing
                                                )
                                            )
                                            .frame(width: 36, height: 36)

                                        Image(systemName: "arrow.up")
                                            .font(.system(size: 14, weight: .semibold))
                                            .foregroundStyle(followUpText.isEmpty ? Color.secondary : Color.white)
                                    }
                                }
                                .buttonStyle(.plain)
                                .disabled(followUpText.isEmpty)
                            }
                        } else {
                            HStack(spacing: 10) {
                                ProgressView()
                                    .scaleEffect(0.8)

                                VStack(alignment: .leading, spacing: 2) {
                                    Text("Thinking...")
                                        .font(.caption)
                                        .foregroundStyle(.primary)

                                    Text(providerManager.activeProviderName ?? "AI")
                                        .font(.caption2)
                                        .foregroundStyle(.secondary)
                                }
                            }
                            .padding(10)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .background(Color.purple.opacity(0.05))
                            .clipShape(RoundedRectangle(cornerRadius: 10))
                        }
                    }

                    // Error display
                    if let error = state.error {
                        VStack(alignment: .leading, spacing: 12) {
                            HStack(spacing: 8) {
                                ZStack {
                                    Circle()
                                        .fill(Color.red.opacity(0.15))
                                        .frame(width: 28, height: 28)

                                    Image(systemName: "exclamationmark.triangle.fill")
                                        .font(.system(size: 12))
                                        .foregroundStyle(.red)
                                }

                                VStack(alignment: .leading, spacing: 2) {
                                    Text("Error")
                                        .font(.caption.weight(.medium))
                                        .foregroundStyle(.red)

                                    Text(error.localizedDescription)
                                        .font(.caption)
                                        .foregroundStyle(.secondary)
                                }
                            }

                            if error.localizedDescription.contains("provider") || error.localizedDescription.contains("configured") {
                                #if os(macOS)
                                Button {
                                    NSApp.sendAction(Selector(("showSettingsWindow:")), to: nil, from: nil)
                                } label: {
                                    HStack(spacing: 4) {
                                        Image(systemName: "gearshape.fill")
                                            .font(.caption)

                                        Text("Open Settings")
                                            .font(.caption)
                                    }
                                    .padding(.horizontal, 12)
                                    .padding(.vertical, 6)
                                    .background(Color.red.opacity(0.15))
                                    .foregroundStyle(.red)
                                    .clipShape(RoundedRectangle(cornerRadius: 6))
                                }
                                .buttonStyle(.plain)
                                #else
                                Text("Configure an AI provider in Settings")
                                    .font(.caption2)
                                    .foregroundStyle(.secondary)
                                #endif
                            }
                        }
                        .padding()
                        .background(Color.red.opacity(0.08))
                        .clipShape(RoundedRectangle(cornerRadius: 10))
                        .overlay(
                            RoundedRectangle(cornerRadius: 10)
