                                    .foregroundStyle(.secondary)
                                    .monospacedDigit()
                                    .padding(.horizontal, 6)
                                    .padding(.vertical, 2)
                                    .background(Color.blue.opacity(0.1))
                                    .clipShape(Capsule())
                            }
                            .padding(.horizontal, 8)

                            ForEach(chapterHighlights) { highlight in
                                HighlightRow(highlight: highlight)
                            }
                        }
                        .padding(.top, 8)
                    }
                }
                .padding()
            }
        }
}

