   141→    },
   142→
   143→    pendingHighlightId: null,
   144→
   145→    createNoteForHighlight: function(highlightId, preview) {
   146→        const highlight = document.querySelector('[data-highlight-id="' + highlightId + '"]');
   147→        if (!highlight || !this.marginRight) return;
   148→
   149→        this.removeNote(highlightId);
   150→
   151→        const top = this.getDocumentOffset(highlight);
   152→
   153→        const note = document.createElement('div');
   154→        note.className = 'crux-margin-note';
   155→        note.dataset.highlightId = highlightId;
   156→        note.dataset.idealTop = top;
   157→        note.dataset.side = 'right';
   158→        note.style.top = top + 'px';
   159→
   160→        note.innerHTML = '<div class="preview">' + this.escapeHTML(preview) + '</div>' +
   161→            '<button class="crux-start-thread">Annotate</button>';
   162→
   163→        this.marginRight.appendChild(note);
   164→        this.notes.set(highlightId, note);
   165→
   166→        requestAnimationFrame(() => this.resolveCollisions());
   167→    },
   168→
   169→    updateNotes: function(notesData) {
   170→        // Ensure margins are initialized
   171→        if (!this.marginRight || !this.marginLeft) {
   172→            this.marginLeft = document.querySelector('.crux-margin-left');
   173→            this.marginRight = document.querySelector('.crux-margin-right');
   174→        }
   175→        if (!this.marginRight) return;
   176→
   177→        // Track pending highlight ID for keyboard shortcuts
   178→        this.pendingHighlightId = null;
   179→
   180→        // Remove notes that are no longer in the data (e.g., old pending selection)
   181→        const newIds = new Set(notesData.map(d => d.highlightId));
   182→        for (const [highlightId, note] of this.notes) {
   183→            if (!newIds.has(highlightId)) {
   184→                this.removeNote(highlightId);
   185→            }
   186→        }
   187→
   188→        for (const data of notesData) {
   189→            // Track uncommitted selection for keyboard shortcuts
   190→            if (!data.isCommitted) {
   191→                this.pendingHighlightId = data.highlightId;
   192→            }
   193→
   194→            let note = this.notes.get(data.highlightId);
   195→
   196→            if (!note) {
   197→                const highlight = document.querySelector('[data-highlight-id="' + data.highlightId + '"]');
   198→                if (!highlight) continue;
   199→
   200→                note = document.createElement('div');
   201→                note.className = 'crux-margin-note';
   202→                note.dataset.highlightId = data.highlightId;
   203→                note.dataset.idealTop = this.getDocumentOffset(highlight);
   204→                note.dataset.side = 'right';
   205→                note.style.top = note.dataset.idealTop + 'px';
   206→                this.marginRight.appendChild(note);
   207→                this.notes.set(data.highlightId, note);
   208→            }
   209→
   210→            note.innerHTML = this.buildNoteContent(data);
   211→        }
   212→
   213→        requestAnimationFrame(() => this.resolveCollisions());
   214→    },
   215→
   216→    buildNoteContent: function(data) {
   217→        let html = '<div class="note-header"><div class="preview">' + this.escapeHTML(data.previewText) + '</div>';
   218→        html += '<button class="crux-delete-highlight" title="Delete">\u00d7</button></div>';
   219→
   220→        if (data.isLoading) {
   221→            html += '<div class="crux-loading">' + (data.hasThread ? 'Thinking...' : 'Analyzing...') + '</div>';
   222→        } else if (data.hasThread && data.threadContent) {
   223→            html += '<div class="thread-content">' + data.threadContent + '</div>';
   224→            // No inline input - using floating input bar instead
   225→        } else if (!data.isCommitted) {
   226→            // Uncommitted selection - show both buttons
   227→            html += '<div class="crux-selection-actions">' +
   228→                '<button class="crux-commit-highlight">Highlight</button>' +
   229→                '<button class="crux-start-thread">Annotate</button>' +
   230→                '</div>';
   231→        } else {
   232→            // Committed but no thread
   233→            html += '<button class="crux-start-thread">Annotate</button>';
   234→        }
   235→
   236→        return html;
   237→    },
   238→
   239→    removeNote: function(highlightId) {
   240→        const note = this.notes.get(highlightId);
   241→        if (note) {
   242→            note.remove();
   243→            this.notes.delete(highlightId);
   244→        }
   245→    },
   246→
   247→    clearAllNotes: function() {
   248→        for (const note of this.notes.values()) {
   249→            note.remove();
   250→        }
   251→        this.notes.clear();
   252→    },
   253→
   254→    getDocumentOffset: function(el) {
   255→        let top = 0;
   256→        let current = el;
   257→        while (current && current !== document.body) {
   258→            top += current.offsetTop;
   259→            current = current.offsetParent;
   260→        }
   261→        return top;
   262→    },
   263→
   264→    resolveCollisions: function() {
   265→        // Ensure margins are initialized
   266→        if (!this.marginRight || !this.marginLeft) {
   267→            this.marginLeft = document.querySelector('.crux-margin-left');
   268→            this.marginRight = document.querySelector('.crux-margin-right');
   269→        }
   270→        if (!this.marginRight || !this.marginLeft) return;
   271→
   272→        const notesList = Array.from(this.notes.values())
   273→            .map(el => ({
   274→                el: el,
   275→                idealTop: parseFloat(el.dataset.idealTop) || 0,
   276→                height: el.offsetHeight
   277→            }))
   278→            .sort((a, b) => a.idealTop - b.idealTop);
   279→
   280→        const GAP = 8;
   281→        const OVERLAP_THRESHOLD = 40; // Move to left if would be pushed down more than this
   282→        let rightBottom = 0;
   283→        let leftBottom = 0;
   284→
   285→        for (const note of notesList) {
   286→            const wouldBeOnRight = Math.max(note.idealTop, rightBottom);
   287→            const pushAmount = wouldBeOnRight - note.idealTop;
   288→
   289→            // If note would be pushed down significantly, try left side
   290→            if (pushAmount > OVERLAP_THRESHOLD && note.idealTop >= leftBottom) {
   291→                // Move to left side
   292→                if (note.el.dataset.side !== 'left') {
   293→                    note.el.dataset.side = 'left';
   294→                    this.marginLeft.appendChild(note.el);
   295→                }
   296→                const resolvedTop = Math.max(note.idealTop, leftBottom);
   297→                note.el.style.top = resolvedTop + 'px';
   298→                leftBottom = resolvedTop + note.height + GAP;
   299→            } else {
   300→                // Keep on right side
   301→                if (note.el.dataset.side !== 'right') {
   302→                    note.el.dataset.side = 'right';
   303→                    this.marginRight.appendChild(note.el);
   304→                }
   305→                note.el.style.top = wouldBeOnRight + 'px';
   306→                rightBottom = wouldBeOnRight + note.height + GAP;
   307→            }
   308→        }
   309→    },
   310→
   311→    escapeHTML: function(str) {
   312→        const div = document.createElement('div');
   313→        div.textContent = str;
   314→        return div.innerHTML;
   315→    }
   316→};
   317→
   318→if (document.readyState === 'loading') {
   319→    document.addEventListener('DOMContentLoaded', () => CruxMarginNotes.init());
   320→} else {
   321→    CruxMarginNotes.init();
   322→}
