/* Crux Reader Styles */

:root {
    --crux-bg: #FFFFFF;
    --crux-text: #2C2825;
    --crux-text-muted: #6B6561;
    --crux-accent: #8B4513;
    --crux-selection: rgba(139, 69, 19, 0.18);
    --crux-rule: rgba(44, 40, 37, 0.12);
    --crux-highlight: rgba(139, 69, 19, 0.15);
    --crux-highlight-hover: rgba(139, 69, 19, 0.25);
    --crux-font-body: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
    --crux-font-display: "New York", "Iowan Old Style", Georgia, serif;
    --crux-font-ui: -apple-system, BlinkMacSystemFont, sans-serif;
}

@media (prefers-color-scheme: dark) {
    :root {
        --crux-bg: #1C1A18;
        --crux-text: #E8E4DF;
        --crux-text-muted: #9A958F;
        --crux-accent: #D4A574;
        --crux-selection: rgba(212, 165, 116, 0.25);
        --crux-rule: rgba(232, 228, 223, 0.1);
        --crux-highlight: rgba(212, 165, 116, 0.2);
        --crux-highlight-hover: rgba(212, 165, 116, 0.35);
    }
}

/* Base */
html, body {
    margin: 0;
    padding: 0;
    background: var(--crux-bg);
    -webkit-font-smoothing: antialiased;
}

/* Layout */
.crux-reader-wrapper {
    display: flex;
    max-width: 1400px;
    margin: 0 auto;
    justify-content: center;
}

.crux-content {
    flex: 0 1 680px;
    padding: 48px 56px;
    font-family: var(--crux-font-body);
    font-size: 18px;
    line-height: 1.75;
    letter-spacing: 0.01em;
    color: var(--crux-text);
    text-rendering: optimizeLegibility;
    font-feature-settings: "kern" 1, "liga" 1;
}

.crux-margin {
    flex: 0 0 280px;
    position: relative;
    padding: 48px 12px;
}

.crux-margin-left {
    padding-left: 12px;
    padding-right: 0;
}

.crux-margin-right {
    padding-left: 0;
    padding-right: 12px;
}

/* iOS platform overrides */
:root[data-platform="ios"] .crux-content {
    padding: 24px 20px;
}

:root[data-platform="ios"] .crux-reader-wrapper {
    max-width: 1100px;
}

/* Paragraphs */
.crux-content p {
    margin: 0 0 1.5em 0;
    text-align: justify;
    hyphens: auto;
    -webkit-hyphens: auto;
}

.crux-content p + p {
    text-indent: 1.5em;
    margin-top: -0.5em;
}

/* Headings */
.crux-content h1, .crux-content h2, .crux-content h3, .crux-content h4 {
    font-family: var(--crux-font-display);
    font-weight: 500;
    letter-spacing: -0.01em;
    line-height: 1.25;
    margin: 2em 0 0.75em 0;
    color: var(--crux-text);
    text-indent: 0;
}

.crux-content h1 {
    font-size: 2em;
    font-weight: 400;
    letter-spacing: -0.02em;
    margin-top: 0;
    margin-bottom: 1.5em;
    text-align: center;
}

.crux-content h2 {
    font-size: 1.4em;
    margin-top: 2.5em;
    padding-top: 1.5em;
    border-top: 1px solid var(--crux-rule);
}

.crux-content h3 {
    font-size: 1.15em;
    font-style: italic;
    font-weight: 400;
}

/* Blockquotes */
.crux-content blockquote {
    margin: 2em 0;
    padding: 0 0 0 1.5em;
    border-left: 2px solid var(--crux-rule);
    font-style: italic;
    color: var(--crux-text-muted);
}

.crux-content blockquote p {
    text-indent: 0;
    text-align: left;
}

.crux-content h1 + blockquote,
.crux-content h2 + blockquote {
    border-left: none;
    padding: 0;
    margin: -0.5em 2em 2.5em 2em;
    text-align: right;
    font-size: 0.9em;
}

/* Links */
.crux-content a {
    color: inherit;
    text-decoration-color: var(--crux-accent);
    text-decoration-thickness: 1px;
    text-underline-offset: 0.15em;
}

/* Lists */
.crux-content ul, .crux-content ol {
    margin: 1.5em 0;
    padding-left: 1.5em;
}

.crux-content li {
    margin-bottom: 0.5em;
    text-indent: 0;
}

.crux-content li::marker {
    color: var(--crux-text-muted);
}

/* Horizontal rules */
.crux-content hr {
    border: none;
    margin: 3em auto;
    text-align: center;
    color: var(--crux-text-muted);
}

.crux-content hr::before {
    content: "\2022  \2022  \2022";
    letter-spacing: 0.5em;
}

/* Images */
.crux-content img {
    max-width: 100%;
    height: auto;
    display: block;
    margin: 2em auto;
}

/* Selection */
::selection {
    background: var(--crux-selection);
}

/* Highlights */
.crux-highlight {
    background-color: var(--crux-highlight);
    border-radius: 2px;
    cursor: pointer;
    transition: background-color 0.2s ease;
}

.crux-highlight:hover {
    background-color: var(--crux-highlight-hover);
}

/* Margin notes */
.crux-margin-note {
    position: absolute;
    width: 252px;
    padding: 12px;
    background: var(--crux-rule);
    border-radius: 6px;
    font-family: var(--crux-font-ui);
    font-size: 13px;
    line-height: 1.5;
    color: var(--crux-text);
}

.crux-margin-right .crux-margin-note {
    right: 12px;
}

.crux-margin-left .crux-margin-note {
    left: 12px;
}

.crux-margin-note .note-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 8px;
    margin-bottom: 10px;
}

.crux-margin-note .preview {
    flex: 1;
    font-family: var(--crux-font-body);
    font-style: italic;
    color: var(--crux-text-muted);
    font-size: 12px;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.crux-delete-highlight {
    appearance: none;
    border: none;
    background: transparent;
    color: var(--crux-text-muted);
    font-size: 16px;
    line-height: 1;
    padding: 0 4px;
    cursor: pointer;
    opacity: 0.5;
    transition: opacity 0.15s ease;
}

.crux-delete-highlight:hover {
    opacity: 1;
    color: var(--crux-accent);
}

.crux-margin-note .thread-content {
    margin-bottom: 8px;
}

.crux-margin-note .thread-message {
    margin-bottom: 10px;
}

.crux-margin-note .thread-message.user {
    font-style: italic;
    color: var(--crux-text-muted);
    font-size: 12px;
}

.crux-margin-note .thread-message.user::before {
    content: "You: ";
    font-weight: 500;
}

.crux-margin-note .thread-message.assistant {
    color: var(--crux-text);
}

.crux-margin-note .thread-message strong {
    font-weight: 600;
}

.crux-margin-note .thread-message em {
    font-style: italic;
}

.crux-margin-note .thread-message code {
    font-family: ui-monospace, "SF Mono", Menlo, monospace;
    font-size: 0.9em;
    background: var(--crux-rule);
    padding: 1px 4px;
    border-radius: 3px;
}

.crux-selection-actions {
    display: flex;
    gap: 6px;
}

.crux-commit-highlight,
.crux-start-thread {
    appearance: none;
    border: 1px solid var(--crux-rule);
    background: var(--crux-bg);
    border-radius: 5px;
    padding: 6px 10px;
    font-size: 12px;
    font-family: var(--crux-font-ui);
    color: var(--crux-text);
    cursor: pointer;
}

.crux-commit-highlight:hover,
.crux-start-thread:hover {
    background: var(--crux-rule);
}

.crux-margin-note.active {
    outline: 2px solid var(--crux-accent);
    outline-offset: 2px;
}

/* Floating input */
.crux-floating-input {
    position: fixed;
    bottom: 24px;
    right: 24px;
    width: 300px;
    background: var(--crux-bg);
    border: 1px solid var(--crux-accent);
    border-radius: 10px;
    padding: 12px 14px;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.18);
    z-index: 100;
    opacity: 0;
    transform: translateY(10px);
    transition: opacity 0.2s ease, transform 0.2s ease;
    pointer-events: none;
}

.crux-floating-input.visible {
    opacity: 1;
    transform: translateY(0);
    pointer-events: auto;
}

.crux-floating-input-context {
    font-family: var(--crux-font-body);
    font-size: 11px;
    font-style: italic;
    color: var(--crux-text-muted);
    margin-bottom: 8px;
    display: -webkit-box;
    -webkit-line-clamp: 1;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.crux-floating-input input {
    width: 100%;
    border: none;
    background: transparent;
    font-family: var(--crux-font-ui);
    font-size: 14px;
    color: var(--crux-text);
    outline: none;
}

.crux-floating-input input::placeholder {
    color: var(--crux-text-muted);
}

.crux-floating-input-hint {
    font-family: var(--crux-font-ui);
    font-size: 10px;
    color: var(--crux-text-muted);
    margin-top: 6px;
    opacity: 0.7;
}

/* Loading state */
.crux-loading {
    display: flex;
    align-items: center;
    gap: 6px;
    color: var(--crux-text-muted);
    font-size: 12px;
}

.crux-loading::before {
    content: "";
    width: 12px;
    height: 12px;
    border: 2px solid var(--crux-rule);
    border-top-color: var(--crux-accent);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}

@keyframes spin {
    to {
        transform: rotate(360deg);
    }
}

/* Search highlights */
.crux-search-highlight {
    background-color: rgba(255, 230, 0, 0.4);
    border-radius: 2px;
}

.crux-search-highlight.crux-search-current {
    background-color: rgba(255, 165, 0, 0.7);
    box-shadow: 0 0 0 2px rgba(255, 165, 0, 0.4);
}

@media (prefers-color-scheme: dark) {
    .crux-search-highlight {
        background-color: rgba(255, 230, 0, 0.3);
    }

    .crux-search-highlight.crux-search-current {
        background-color: rgba(255, 165, 0, 0.5);
        box-shadow: 0 0 0 2px rgba(255, 165, 0, 0.3);
    }
}
